-- Gupta Enterprises: database schema for Neon (Postgres + Data API + Clerk sign-in).
-- Generated by neon/build_schema.sh from supabase/migrations; edit those or neon/extras.sql, not this file.
create extension if not exists pgcrypto;
create extension if not exists pg_trgm;
create extension if not exists unaccent;
create extension if not exists pg_session_jwt;   -- auth.user_id() and auth.session() from the Clerk token

do $$ begin
  if not exists (select 1 from pg_roles where rolname = 'anonymous') then create role anonymous nologin; end if;
  if not exists (select 1 from pg_roles where rolname = 'authenticated') then create role authenticated nologin; end if;
end $$;

-- Keys the server needs (email, WhatsApp gateway, distance signing). Not reachable through the Data API.
create schema if not exists private;
create table if not exists private.secrets (
  name text primary key,
  decrypted_secret text not null,
  updated_at timestamptz not null default now()
);
revoke all on schema private from public;

-- The signed-in shopper. Clerk ids ("user_2abc...") become a stable uuid, so every table keeps uuid keys.
create or replace function public.uid() returns uuid
language sql stable set search_path = '' as $$
  select case when coalesce(auth.user_id(), '') = '' then null else md5('clerk:' || auth.user_id())::uuid end
$$;
create or replace function public.jwt() returns jsonb
language sql stable set search_path = '' as $$ select coalesce(auth.session(), '{}'::jsonb) $$;
