-- Name: _html(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._html(t text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select replace(replace(replace(coalesce(t, ''), '&', '&amp;'), '<', '&lt;'), '>', '&gt;')
$$;


