-- Name: _inr(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._inr(p integer) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
  select '₹' || regexp_replace(to_char(p / 100.0, 'FM999999990.00'), '\.00$', '')
$_$;


